class Solution {
    private int[] tmp;

    public int[] sortArray(int[] nums) {
        tmp = new int[nums.length];
        mergeSort(nums, 0, nums.length - 1);
        return nums;
    }

    // 把 nums[l..r] 排好
    private void mergeSort(int[] nums, int l, int r) {
        if (l >= r) {
            return;
        }
        int mid = l + (r - l) / 2;
        mergeSort(nums, l, mid);                // 先把两半各自排好
        mergeSort(nums, mid + 1, r);
        int i = l, j = mid + 1, k = l;          // 合并两个有序的半段
        while (i <= mid && j <= r) {
            if (nums[i] <= nums[j]) {           // 相等时先拿左边的：稳定
                tmp[k++] = nums[i++];
            } else {
                tmp[k++] = nums[j++];
            }
        }
        while (i <= mid) {                      // 一边用完了，另一边剩下的直接接上
            tmp[k++] = nums[i++];
        }
        while (j <= r) {
            tmp[k++] = nums[j++];
        }
        System.arraycopy(tmp, l, nums, l, r - l + 1);   // 拷回原数组
    }
}

