        snap("完成", `排好了：[${nums.join(", ")}]。`, view(), {
          at: "done",
          kind: "ok",
          ans: nums.slice(),
          facts: [["当前合并", "全部完成"], ["结果", `[${nums.join(", ")}]`]],
        });
      }

