class Solution {
    private int[] tmp;

    public int reversePairs(int[] record) {
        tmp = new int[record.length];
        return sort(record, 0, record.length - 1);
    }

    // 排好 record[l..r]，返回里面的逆序对数
    private int sort(int[] record, int l, int r) {
        if (l >= r) {
            return 0;
        }
        int mid = l + (r - l) / 2;
        int cnt = sort(record, l, mid) + sort(record, mid + 1, r);  // 两半内部的逆序对
        int i = l, j = mid + 1, k = l;
        while (i <= mid && j <= r) {
            if (record[i] <= record[j]) {
                tmp[k++] = record[i++];
            } else {                            // 右边的更小：左边剩下的都比它大
                cnt += mid - i + 1;
                tmp[k++] = record[j++];
            }
        }
        while (i <= mid) {
            tmp[k++] = record[i++];
        }
        while (j <= r) {
            tmp[k++] = record[j++];
        }
        System.arraycopy(tmp, l, record, l, r - l + 1);
        return cnt;
    }
}

