    const tmp: number[] = new Array(record.length);
    // 排好 record[l..r]，返回里面的逆序对数
    const sort = (l: number, r: number): number => {
        if (l >= r) {
            return 0;
        }
        const mid = (l + r) >> 1;
        let cnt = sort(l, mid) + sort(mid + 1, r);  // 两半内部的逆序对
        let i = l, j = mid + 1, k = l;
        while (i <= mid && j <= r) {
            if (record[i] <= record[j]) {
                tmp[k++] = record[i++];
            } else {                            // 右边的更小：左边剩下的都比它大
                cnt += mid - i + 1;
                tmp[k++] = record[j++];
